function renderPermBadge(p, roleId, secKey) {
  if (!p || (!p.view && !p.create && !p.edit && !p.delete && !p.approve && !p.export)) {
    return `<span class="rbac-perm-capsule none" title="No permissions granted for this domain" onclick="openEditRoleModal('${roleId}')">⚪ Restricted</span>`;
  }
  if (p.view && p.create && p.edit && p.delete && p.approve && p.export) {
    return `<span class="rbac-perm-capsule full" title="Full Unconstrained Administrative Access" onclick="openEditRoleModal('${roleId}')">🟢 Full Control</span>`;
  }
  if (p.approve || (p.create && p.edit)) {
    return `<span class="rbac-perm-capsule operational" title="Operational: Read, Write & Execute" onclick="openEditRoleModal('${roleId}')">🔵 Operational</span>`;
  }
  return `<span class="rbac-perm-capsule audit" title="Read & Audit Only" onclick="openEditRoleModal('${roleId}')">🟡 Read / Audit</span>`;
}


function renderUserWarehouseBadges(whAccess) {
  if (!whAccess || whAccess === "Unassigned") {
    return `<span class="badge" style="background: rgba(239, 68, 68, 0.1); color: var(--danger); font-size: 10px; border: 1px solid rgba(239, 68, 68, 0.3);">⚠️ Unassigned</span>`;
  }
  const isGlobal = whAccess.toLowerCase().includes("all warehouses") || whAccess.toLowerCase().includes("global");
  if (isGlobal) {
    return `
      <span class="rbac-wh-tag" style="border-color: var(--brand-cyan); background: rgba(6, 182, 212, 0.1); color: var(--brand-cyan); font-weight: 700;">
        <span>🌐</span>
        <span>Global (All ${AppState.warehouses.length} Facilities)</span>
      </span>
    `;
  }
  const parts = whAccess.split(",").map(s => s.trim()).filter(Boolean);
  return `
    <div style="display: flex; flex-wrap: wrap; gap: 4px;">
      ${parts.map(p => {
    const flag = p.includes("India") || p.includes("Bhadohi") ? "🇮🇳" :
      p.includes("USA") || p.includes("Edison") ? "🇺🇸" :
        p.includes("ICD") || p.includes("Babatpur") || p.includes("Delhi") ? "🏛️" :
          p.includes("Europe") || p.includes("Frankfurt") ? "🇪🇺" :
            p.includes("FBA") ? "📦" : "🏭";
    return `
          <span class="rbac-wh-tag" title="Authorized: ${p}">
            <span>${flag}</span>
            <span>${p}</span>
          </span>
        `;
  }).join('')}
    </div>
  `;
}

function toggleAllUserWh(selectAll, inputName) {
  const cbs = document.querySelectorAll(`input[name="${inputName}"]`);
  cbs.forEach(cb => cb.checked = selectAll);
}


const WAREHOUSE_PERM_ACTIONS = [
  { key: "viewStock", label: "View Stock", icon: "👁️", desc: "View physical inventory, bins & ledger balance" },
  { key: "inwardGRN", label: "Inward / GRN", icon: "📥", desc: "Scan goods receipt, unpack ocean containers" },
  { key: "packingQC", label: "Packing & QC", icon: "🔍", desc: "Execute QC checks, photo proofs, generate packing slips" },
  { key: "dispatchShipping", label: "Dispatch / Ship", icon: "✈️", desc: "Print carrier labels, dock manifest & staging" },
  { key: "stockAdjustment", label: "Stock Adjust", icon: "⚖️", desc: "Physical cycle count write-offs & grade changes" },
  { key: "transferOut", label: "Transfer Out", icon: "🔄", desc: "Initiate inter-warehouse replenishment transfers" }
];

function getRoleWarehousePerms(role, whId) {
  if (role.warehousePermissions && role.warehousePermissions[whId]) {
    return role.warehousePermissions[whId];
  }
  const isSuperAdmin = role.id === "role_admin" || (role.name && role.name.toLowerCase().includes("admin"));
  if (isSuperAdmin) {
    return { viewStock: true, inwardGRN: true, packingQC: true, dispatchShipping: true, stockAdjustment: true, transferOut: true };
  }
  const rName = (role.name || "").toLowerCase();
  const isIndiaWh = rName.includes("india") && rName.includes("warehouse");
  const isUsa3pl = rName.includes("usa") || rName.includes("3pl");
  const isExport = rName.includes("export");
  const isAuditor = rName.includes("audit") || rName.includes("finance") || rName.includes("controller");

  if (isIndiaWh) {
    if (whId === "WH-IND-01") return { viewStock: true, inwardGRN: true, packingQC: true, dispatchShipping: true, stockAdjustment: true, transferOut: true };
    if (whId === "WH-IND-02") return { viewStock: true, inwardGRN: false, packingQC: false, dispatchShipping: true, stockAdjustment: false, transferOut: true };
    return { viewStock: true, inwardGRN: false, packingQC: false, dispatchShipping: false, stockAdjustment: false, transferOut: false };
  }
  if (isUsa3pl) {
    if (whId === "WH-USA-01") return { viewStock: true, inwardGRN: true, packingQC: true, dispatchShipping: true, stockAdjustment: true, transferOut: true };
    if (whId === "WH-USA-FBA") return { viewStock: true, inwardGRN: true, packingQC: false, dispatchShipping: false, stockAdjustment: false, transferOut: true };
    return { viewStock: false, inwardGRN: false, packingQC: false, dispatchShipping: false, stockAdjustment: false, transferOut: false };
  }
  if (isExport) {
    if (whId === "WH-IND-01" || whId === "WH-IND-02") return { viewStock: true, inwardGRN: false, packingQC: false, dispatchShipping: true, stockAdjustment: false, transferOut: true };
    return { viewStock: true, inwardGRN: false, packingQC: false, dispatchShipping: false, stockAdjustment: false, transferOut: false };
  }
  if (isAuditor) {
    return { viewStock: true, inwardGRN: false, packingQC: false, dispatchShipping: false, stockAdjustment: false, transferOut: false };
  }
  return { viewStock: true, inwardGRN: false, packingQC: false, dispatchShipping: false, stockAdjustment: false, transferOut: false };
}

function renderWhPermSummaryBadge(permObj, roleId, whId) {
  if (!permObj) {
    return `<span class="rbac-perm-capsule none" title="Click to Configure" onclick="openEditRoleWhModal('${roleId}', '${whId}')">⚪ Restricted</span>`;
  }
  const isFull = permObj.viewStock && permObj.inwardGRN && permObj.packingQC && permObj.dispatchShipping && permObj.stockAdjustment && permObj.transferOut;
  if (isFull) {
    return `<span class="rbac-perm-capsule full" title="Full Warehouse Operations Authority" onclick="openEditRoleWhModal('${roleId}', '${whId}')">🟢 Full Control</span>`;
  }
  const isNone = !permObj.viewStock && !permObj.inwardGRN && !permObj.packingQC && !permObj.dispatchShipping && !permObj.stockAdjustment && !permObj.transferOut;
  if (isNone) {
    return `<span class="rbac-perm-capsule none" title="Strictly Restricted by SoD Policy" onclick="openEditRoleWhModal('${roleId}', '${whId}')">⚪ Restricted</span>`;
  }
  const isViewOnly = permObj.viewStock && !permObj.inwardGRN && !permObj.packingQC && !permObj.dispatchShipping && !permObj.stockAdjustment && !permObj.transferOut;
  if (isViewOnly) {
    return `<span class="rbac-perm-capsule audit" title="Read & Audit Only" onclick="openEditRoleWhModal('${roleId}', '${whId}')">🟡 Read / Audit</span>`;
  }

  const acts = [];
  if (permObj.inwardGRN) acts.push("Inward");
  if (permObj.packingQC) acts.push("QC");
  if (permObj.dispatchShipping) acts.push("Ship");
  if (permObj.stockAdjustment) acts.push("Adjust");
  if (permObj.transferOut) acts.push("Transfer");

  const label = acts.slice(0, 2).join(' • ') + (acts.length > 2 ? ` +${acts.length - 2}` : '');
  return `<span class="rbac-perm-capsule operational" title="Permitted: ${acts.join(', ')}" onclick="openEditRoleWhModal('${roleId}', '${whId}')">🔵 ${label}</span>`;
}

function openEditRoleWhModal(roleId, focusWhId) {
  openEditRoleModal(roleId, 'warehouses', focusWhId);
}

function switchRoleModalTab(roleId, tabName) {
  openEditRoleModal(roleId, tabName);
}

function presetSingleRoleWh(whId, mode) {
  const cbs = document.querySelectorAll(`.role-wh-checkbox-${whId}`);
  cbs.forEach(cb => {
    if (mode === 'full') cb.checked = true;
    else if (mode === 'none') cb.checked = false;
    else if (mode === 'view') cb.checked = cb.id.endsWith('_viewStock');
    else if (mode === 'fulfillment') {
      cb.checked = cb.id.endsWith('_viewStock') || cb.id.endsWith('_inwardGRN') || cb.id.endsWith('_packingQC') || cb.id.endsWith('_dispatchShipping');
    }
  });
}

function presetAllRoleWh(roleId, mode) {
  AppState.warehouses.forEach(w => presetSingleRoleWh(w.id, mode));
}

