function saveNewUser() {
  const name = document.getElementById("formUserName").value.trim() || "New Operator";
  const email = document.getElementById("formUserEmail").value.trim() || "user@rugos.in";
  const role = document.getElementById("formUserRole").value;
  const status = document.getElementById("formUserStatus").value;

  const checkedBoxes = Array.from(document.querySelectorAll('input[name="userWhCheckbox"]:checked')).map(cb => cb.value);
  let whAccess = "Unassigned";
  if (checkedBoxes.length === AppState.warehouses.length) {
    whAccess = "All Warehouses (Global)";
  } else if (checkedBoxes.length > 0) {
    whAccess = checkedBoxes.join(", ");
  }

  const newUser = {
    name,
    email,
    role,
    status,
    whAccess,
    perm: "Standard Operational Access"
  };

  // Update user count in role
  const r = AppState.roles.find(roleObj => roleObj.name === role);
  if (r) r.userCount = (r.userCount || 0) + 1;

  AppState.users.push(newUser);
  closeModal("crudModal");
  showToast(`User ${name} granted access for [${whAccess}] with role ${role}.`, "success");
  renderCurrentView();
}

