function saveNewOrder() {
  const orderId = document.getElementById("formOrderId").value.trim();
  const channel = document.getElementById("formOrderChannel").value;
  const buyer = document.getElementById("formOrderBuyer").value.trim() || "Valued Client";
  const email = document.getElementById("formOrderEmail").value.trim() || "client@domain.com";
  const address = document.getElementById("formOrderAddress").value.trim() || "New York, NY, United States";
  const skuCode = document.getElementById("formOrderSku").value;
  const qty = parseInt(document.getElementById("formOrderQty").value) || 1;
  const wh = document.getElementById("formOrderWh").value;

  const sku = AppState.skus.find(s => s.sku === skuCode) || AppState.skus[0];
  const unitPrice = sku.sellingPriceUSD;
  const subtotal = unitPrice * qty;
  const tax = subtotal * 0.0825;
  const total = subtotal + tax;

  const channelNames = { amazon: "Amazon US", etsy: "Etsy Direct", walmart: "Walmart US", b2b: "B2B Wholesale Export" };

  const newOrder = {
    orderId,
    channel: channelNames[channel],
    channelIcon: channel,
    marketplaceOrderId: `API-${Date.now().toString().slice(-8)}`,
    orderDate: new Date().toISOString().replace('T', ' ').slice(0, 19) + " UTC",
    buyerName: buyer,
    buyerEmail: email,
    buyerPhone: "+1 (555) 019-2834",
    shippingAddress: address,
    billingAddress: "Same as Shipping Address",
    sku: skuCode,
    qty,
    unitPriceUSD: unitPrice,
    subtotalUSD: subtotal,
    shippingChargedUSD: 0.00,
    taxUSD: tax,
    totalOrderUSD: total,
    status: "Imported & Mapped",
    fulfillmentWh: wh,
    stockAllocation: `Allocated to ${wh.split(' ')[0]}`,
    allocationTimestamp: new Date().toISOString(),
    courier: "FedEx Standard Priority",
    awb: `7894-${Math.floor(1000 + Math.random() * 9000)}-${Math.floor(100 + Math.random() * 900)}`,
    labelGenerated: false,
    trackingStatus: "Manifest Generated — Ready for Pick",
    shippingCostEst: 42.00,
    shippingCostAct: 42.00,
    exportInvoice: `EXP-INV-2026-${Math.floor(200 + Math.random() * 800)}`,
    mtoNeeded: false,
    mappingException: false,
    history: [{ time: new Date().toISOString().slice(0, 19), action: "Order Created", detail: "Manual entry / API ingestion completed." }]
  };

  // Atomic concurrency stock reservation
  if (wh.includes("USA") || wh.includes("Edison")) {
    if (sku.stock.usaAvailable >= qty) {
      sku.stock.usaAvailable -= qty;
      sku.stock.usaReserved = (sku.stock.usaReserved || 0) + qty;
    } else {
      sku.stock.usaReserved = (sku.stock.usaReserved || 0) + qty;
    }
  } else {
    if (sku.stock.indiaAvailable >= qty) {
      sku.stock.indiaAvailable -= qty;
      sku.stock.indiaPacked = (sku.stock.indiaPacked || 0) + qty;
    } else {
      sku.stock.indiaPacked = (sku.stock.indiaPacked || 0) + qty;
    }
  }

  // Record an immutable transaction entry into the SKU Movement History Ledger
  AppState.skuHistory.unshift({
    timestamp: new Date().toISOString().replace('T', ' ').slice(0, 19),
    sku: sku.sku,
    type: "Order Concurrency Reservation",
    qty: -qty,
    source: wh,
    dest: `Order ${orderId} (${channelNames[channel]})`,
    user: "Ctas Admin / Management",
    ref: `ORD-ALLOC: ${orderId}`
  });

  AppState.orders.unshift(newOrder);
  closeModal("crudModal");
  showToast(`Order ${orderId} created and allocated successfully with concurrency lock!`, "success");
  renderCurrentView();
}

function openEditOrderModal(orderId) {
  const order = AppState.orders.find(o => o.orderId === orderId);
  if (!order) return;

  const modal = document.getElementById("crudModal");
  const title = document.getElementById("crudModalTitle");
  const badge = document.getElementById("crudBadge");
  const body = document.getElementById("crudModalBody");
  const footer = document.getElementById("crudModalFooter");

  badge.textContent = "Edit Order";
  title.textContent = `Edit ${order.orderId} Details`;
  body.innerHTML = `
    <div class="form-grid-2">
      <div class="form-group">
        <label>Customer Name:</label>
        <input type="text" class="form-control" id="editOrderBuyer" value="${order.buyerName}">
      </div>
      <div class="form-group">
        <label>Customer Email:</label>
        <input type="email" class="form-control" id="editOrderEmail" value="${order.buyerEmail}">
      </div>
    </div>
    <div class="form-group">
      <label>Shipping Address:</label>
      <input type="text" class="form-control" id="editOrderAddress" value="${order.shippingAddress}">
    </div>
    <div class="form-grid-2">
      <div class="form-group">
        <label>Status:</label>
        <select class="form-control" id="editOrderStatus">
          <option ${order.status.includes('Imported') ? 'selected' : ''}>Imported & Mapped</option>
          <option ${order.status.includes('Packed') ? 'selected' : ''}>Packed & Handover</option>
          <option ${order.status.includes('Transit') ? 'selected' : ''}>In Transit</option>
          <option ${order.status.includes('Delivered') ? 'selected' : ''}>Delivered</option>
        </select>
      </div>
      <div class="form-group">
        <label>Fulfillment Warehouse:</label>
        <select class="form-control" id="editOrderWh">
          ${AppState.warehouses.map(w => `<option value="${w.name || w.city} (${w.id})" ${order.fulfillmentWh.includes(w.id) || order.fulfillmentWh.includes(w.city) ? 'selected' : ''}>${w.id} — ${w.name || w.city} (${w.country})</option>`).join('')}
        </select>
      </div>
    </div>
  `;
  footer.innerHTML = `
    <button class="btn btn-secondary" onclick="closeModal('crudModal')">Cancel</button>
    <button class="btn btn-primary" onclick="updateOrder('${order.orderId}')">Save Changes</button>
  `;
  modal.style.display = "flex";
}

function updateOrder(orderId) {
  const order = AppState.orders.find(o => o.orderId === orderId);
  if (!order) return;

  order.buyerName = document.getElementById("editOrderBuyer").value.trim();
  order.buyerEmail = document.getElementById("editOrderEmail").value.trim();
  order.shippingAddress = document.getElementById("editOrderAddress").value.trim();
  order.status = document.getElementById("editOrderStatus").value;
  order.fulfillmentWh = document.getElementById("editOrderWh").value;

  closeModal("crudModal");
  showToast(`Order ${orderId} updated successfully!`, "success");
  renderCurrentView();
}

function confirmDeleteOrder(orderId) {
  const modal = document.getElementById("deleteConfirmModal");
  const msg = document.getElementById("deleteModalMessage");
  const btn = document.getElementById("confirmDeleteBtn");

  msg.textContent = `Are you sure you want to permanently delete order "${orderId}"? Stock reservations will be safely released back to available inventory.`;
  btn.onclick = () => {
    AppState.orders = AppState.orders.filter(o => o.orderId !== orderId);
    closeModal("deleteConfirmModal");
    showToast(`Order ${orderId} deleted and stock released.`, "danger");
    if (AppState.activeDetail && AppState.activeDetail.id === orderId) {
      backToListView("mod3");
    } else {
      renderCurrentView();
    }
  };
  modal.style.display = "flex";
}



