function updateSkuImagePreview(url) {
  const img = document.getElementById("skuPreviewImg");
  const fallback = "https://images.unsplash.com/photo-1579656381226-5fc0f0100c3b?w=600&q=80";
  if (img) {
    img.src = url.trim() || fallback;
    img.onerror = () => { img.src = fallback; };
  }
}

function selectSkuPreset(key) {
  const p = RUG_PRESETS[key];
  if (!p) return;

  const setVal = (id, val) => { const el = document.getElementById(id); if (el) el.value = val; };

  setVal("formSkuTitle", p.title);
  setVal("formSkuCode", p.sku);
  setVal("formSkuCollection", p.collection);
  setVal("formSkuMaterial", p.material);
  setVal("formSkuConstruction", p.construction);
  setVal("formSkuSize", p.size);
  setVal("formSkuShape", p.shape);
  setVal("formSkuWeight", p.weightKg);
  setVal("formSkuPrice", p.priceUSD);
  setVal("formSkuCostINR", p.costINR);
  setVal("formSkuImageUrl", p.imageUrl);
  setVal("formSkuAsin", p.asin);

  updateSkuImagePreview(p.imageUrl);
  recalcSkuMargin();
  showToast(`Auto-filled: [${p.title}]`, "info");
}

function recalcSkuMargin() {
  const price = parseFloat(document.getElementById("formSkuPrice")?.value) || 0;
  const costINR = parseFloat(document.getElementById("formSkuCostINR")?.value) || 0;
  const mfgUSD = costINR / 83.9;
  const profitUSD = price - mfgUSD;
  const marginPct = price > 0 ? ((profitUSD / price) * 100) : 0;

  const mfgEl = document.getElementById("skuMfgUsdDisplay");
  const profitEl = document.getElementById("skuGrossProfitDisplay");
  const marginEl = document.getElementById("skuMarginPctDisplay");
  const topBadge = document.getElementById("skuTopMarginBadge");

  if (mfgEl) mfgEl.textContent = `₹${costINR.toLocaleString()} ($${mfgUSD.toFixed(2)})`;
  if (profitEl) {
    profitEl.textContent = `$${profitUSD.toFixed(2)}`;
    profitEl.style.color = profitUSD > 0 ? "var(--success)" : "var(--danger)";
  }
  if (marginEl) {
    marginEl.textContent = `${marginPct.toFixed(1)}%`;
    marginEl.style.color = marginPct >= 50 ? "var(--success)" : marginPct >= 30 ? "var(--warning)" : "var(--danger)";
  }
  if (topBadge) {
    topBadge.textContent = `💰 ${marginPct.toFixed(1)}% Gross Margin ($${profitUSD.toFixed(2)} Profit)`;
    topBadge.className = `badge ${marginPct >= 50 ? 'badge-success' : marginPct >= 30 ? 'badge-warning' : 'badge-danger'}`;
  }
}

function generateRandomBarcode(elemId) {
  const el = document.getElementById(elemId);
  if (el) {
    el.value = `890432190${Math.floor(1000 + Math.random() * 9000)}`;
    showToast("Generated new EAN-13 barcode.", "info");
  }
}

function generateRandomSkuCode(elemId) {
  const el = document.getElementById(elemId);
  if (el) {
    const letters = "ABCDEFGHJKLMNPQRSTUVWXYZ";
    const rndCode = Array.from({ length: 4 }, () => letters[Math.floor(Math.random() * letters.length)]).join("");
    el.value = `SKU-RUG-${rndCode}-0810`;
    showToast("Generated SKU identifier.", "info");
  }
}

function triggerSkuImageUpload() {
  const url = prompt("Enter Rug Image URL:", "https://images.unsplash.com/photo-1579656381226-5fc0f0100c3b?w=600&q=80");
  if (url && url.trim()) {
    const input = document.getElementById("formSkuImageUrl");
    if (input) input.value = url.trim();
    updateSkuImagePreview(url.trim());
    showToast("Rug image updated!", "success");
  }
}

