function updateSku(skuCode) {
  const sku = AppState.skus.find(s => s.sku === skuCode);
  if (!sku) return;

  sku.title = document.getElementById("formSkuTitle")?.value.trim() || sku.title;
  sku.collection = document.getElementById("formSkuCollection")?.value.trim() || sku.collection;
  sku.material = document.getElementById("formSkuMaterial")?.value.trim() || sku.material;
  sku.construction = document.getElementById("formSkuConstruction")?.value.trim() || sku.construction;
  sku.size = document.getElementById("formSkuSize")?.value.trim() || sku.size;
  sku.shape = document.getElementById("formSkuShape")?.value || sku.shape;
  sku.weightKg = parseFloat(document.getElementById("formSkuWeight")?.value) || sku.weightKg;

  sku.sellingPriceUSD = parseFloat(document.getElementById("formSkuPrice")?.value) || sku.sellingPriceUSD;
  sku.mfgCostINR = parseInt(document.getElementById("formSkuCostINR")?.value) || sku.mfgCostINR;
  sku.mfgCostUSD = parseFloat((sku.mfgCostINR / 83.9).toFixed(2));

  sku.imageUrl = document.getElementById("formSkuImageUrl")?.value.trim() || sku.imageUrl;
  sku.barcode = document.getElementById("formSkuBarcode")?.value.trim() || sku.barcode;

  closeModal("crudModal");
  showToast(`Updated master specifications for ${skuCode}!`, "success");
  renderCurrentView();
}

function confirmDeleteSku(skuCode) {
  const modal = document.getElementById("deleteConfirmModal");
  const msg = document.getElementById("deleteModalMessage");
  const btn = document.getElementById("confirmDeleteBtn");

  msg.textContent = `Are you sure you want to delete master SKU "${skuCode}"? Ensure no active orders depend on this SKU.`;
  btn.onclick = () => {
    AppState.skus = AppState.skus.filter(s => s.sku !== skuCode);
    closeModal("deleteConfirmModal");
    showToast(`SKU ${skuCode} deleted from master catalog.`, "danger");
    if (AppState.activeDetail && AppState.activeDetail.id === skuCode) {
      backToListView("mod2-prod");
    } else {
      renderCurrentView();
    }
  };
  modal.style.display = "flex";
}



function confirmDeleteUser(email) {
  const modal = document.getElementById("deleteConfirmModal");
  const msg = document.getElementById("deleteModalMessage");
  const btn = document.getElementById("confirmDeleteBtn");

  msg.textContent = `Are you sure you want to revoke access for ${email}?`;
  btn.onclick = () => {
    AppState.users = AppState.users.filter(u => u.email !== email);
    closeModal("deleteConfirmModal");
    showToast(`User access revoked for ${email}.`, "danger");
    renderCurrentView();
  };
  modal.style.display = "flex";
}

