function confirmPoQcPass(poNumber) {
  const po = (AppState.purchaseOrders || []).find(p => p.poNumber === poNumber);
  if (po) {
    po.status = "QC & Packing";
    closeModal("crudModal");
    showToast(`PO ${poNumber} passed digital scale QC & proof captured! Status updated to "QC & Packing". Now click "+ Inward" to receive stock.`, "success");
    renderCurrentView();
  }
}

