// Global Status Changer for Warehouse Stock Transfers
function changeTransferStatus(shipmentId, newStatus) {
  const rep = (AppState.replenishment || []).find(r => r.shipmentId === shipmentId);
  if (!rep) return;
  const oldStatus = rep.status;
  rep.status = newStatus;
  
  // If changed to Received & Verified, trigger stock unlock automatically
  if (newStatus === "Received & Verified") {
    confirmDestinationArrival(shipmentId);
    return;
  }
  
  showToast(`Transfer ${shipmentId} status updated: "${oldStatus}" ➔ "${newStatus}"`, "success");
  renderCurrentView();
}

