function getSkuTitle(skuCode) {
  const match = AppState.skus.find(s => s.sku === skuCode);
  return match ? match.title : "Custom Handcrafted Rug";
}

function getStatusBadgeClass(status) {
  if (status.includes("Delivered") || status.includes("Approved") || status.includes("Paid") || status.includes("Realized")) return "badge-success";
  if (status.includes("Transit") || status.includes("Packed") || status.includes("In Prod")) return "badge-warning";
  if (status.includes("Disputed") || status.includes("Overdue")) return "badge-danger";
  return "badge-primary";
}

function jumpToSowModule(moduleId) {
  const map = { 1: "mod8-sow", 2: "mod2-prod", 3: "mod3", 4: "mod4-mto", 5: "mod5-ship", 6: "mod6-audit", 7: "mod7-cost", 8: "mod8", 9: "mod8-auto" };
  if (map[moduleId]) switchView(map[moduleId]);
}

