function renderSimStepContent() {
  const body = document.getElementById("e2eModalBody");
  const nextBtn = document.getElementById("simStepNextBtn");
  const steps = [
    { title: "Step 1: Amazon US Order Ingested", text: "Order ORD-AMZ-99214 imported via API webhook. Normalized to internal order schema.", badge: "Module 3" },
    { title: "Step 2: SKU Mapping & Concurrency Allocation", text: "Marketplace ASIN B09X78129K mapped to SKU-RUG-HT-0810-IVR. Hard reservation placed on USA 3PL inventory.", badge: "Module 3" },
    { title: "Step 3: Barcode Scan & Packing Station QC", text: "Warehouse operator scans rug barcode. Dimensions verified (250x30x30 cm, 28.5 kg).", badge: "Module 4" },
    { title: "Step 4: Photographic Proof of Packing Captured", text: "Photos snapped of wool pile and sealed polywrap label. Proof attached to carton history.", badge: "Module 4" },
    { title: "Step 5: Export Commercial Invoice & Shipping Bill Generated", text: "Export Suite generated: EXP-INV-2026-112, Packing List, and Indian Customs CSB-V filing.", badge: "Module 5" },
    { title: "Step 6: Live FedEx Dispatch & Tracking", text: "FedEx Home Delivery label generated (AWB #7894-3321-992). Dispatched from warehouse dock.", badge: "Module 5" },
    { title: "Step 7: Inbound Replenishment & USA Receipt Rule", text: "Replenishment cargo verified upon arrival at Edison NJ 3PL. Physical scan unlocks stock.", badge: "Module 4" },
    { title: "Step 8: Courier Invoice 3-Way Audit", text: "FedEx invoice audited: 28.5 kg billed matches 28.5 kg recorded. Rate cleared for payout.", badge: "Module 6" },
    { title: "Step 9: Bank EBRC Realization & FIRA", text: "Wire proceeds received. HDFC Bank FIRA advice filed. Realization certificate closed on DGFT.", badge: "Module 6" },
    { title: "Step 10: True Cost & Net Profit Recalculated", text: "Audited courier actuals replace estimates. True net profit confirmed at $276.20 (40.6% margin).", badge: "Module 7" }
  ];

  const current = steps[AppState.simStep];
  if (body && current) {
    body.innerHTML = `
      <div style="text-align: center; padding: 20px 0;">
        <span class="badge badge-purple" style="font-size: 12px; margin-bottom: 8px;">${current.badge}</span>
        <h2 style="font-size: 20px; margin-bottom: 12px;">${current.title}</h2>
        <p style="font-size: 14px; color: var(--text-muted); max-width: 600px; margin: 0 auto 24px auto;">${current.text}</p>
        <div style="display: flex; justify-content: center; gap: 8px; margin-bottom: 20px;">
          ${steps.map((_, idx) => `
            <div style="width: 24px; height: 6px; border-radius: 3px; background: ${idx <= AppState.simStep ? 'var(--brand-cyan)' : 'var(--bg-elevated)'};"></div>
          `).join('')}
        </div>
        <div style="font-size: 11px; color: var(--text-dim);">Step ${AppState.simStep + 1} of ${steps.length}</div>
      </div>
  `;
  }

  if (nextBtn) nextBtn.textContent = AppState.simStep === steps.length - 1 ? "✓ Finish Simulation" : "Next Workflow Step ➔";
}

function runNextSimStep() {
  if (AppState.simStep < 9) {
    AppState.simStep++;
    renderSimStepContent();
  } else {
    showToast("Full End-to-End Operational Lifecycle Simulation Passed 100%!", "success");
    closeModal('e2eModal');
  }
}

