function generateNewApiKey() {
  const randHex = Array.from({ length: 32 }, () => Math.floor(Math.random() * 16).toString(16)).join('');
  const newToken = `rugos_live_sec_${randHex}`;
  const display = document.getElementById("activeApiTokenDisplay");
  if (display) display.textContent = newToken;
  showToast("New 256-bit API Bearer Token generated successfully!", "success");
}

