function exportCarrierInvoiceCSV(awb) {
  const a = AppState.courierAudit.find(item => item.awb === awb) || AppState.courierAudit[0];
  let csv = "Line Item,Carrier Invoiced Charge,Contract Tariff,Variance USD\n";
  csv += `Base Freight Charge,$${(a.carrierBilledRateUSD * 0.7).toFixed(2)},$${(a.systemExpectedRateUSD * 0.7).toFixed(2)},+$${(a.varianceUSD * 0.7).toFixed(2)}\n`;
  csv += `Volumetric Catch-Weight Penalty,$${(a.carrierBilledRateUSD * 0.2).toFixed(2)},$0.00,+$${(a.varianceUSD * 0.2).toFixed(2)}\n`;
  csv += `Fuel Surcharge (14.5%),$${(a.carrierBilledRateUSD * 0.1).toFixed(2)},$${(a.systemExpectedRateUSD * 0.1).toFixed(2)},+$${(a.varianceUSD * 0.1).toFixed(2)}\n`;
  triggerDownload(`${awb}_Carrier_Invoice_Breakdown.csv`, csv, "text/csv");
}
